    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endRFS(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // MATERIAL_ID
        $builder->required($o, 72);  // PROVENANCE
        return $o;
    }

    public static function finishRFSBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$RFS");
    }
